%%\ Lab 1: Image as a 2D Signal (Sampling, Quantization, Histograms, Enhancement)
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

%%\ 0) Load and inspect an image
if exist('peppers.png', 'file')
    I_rgb = imread('peppers.png');
else
    I_rgb = repmat(imread('cameraman.tif'), 1, 1, 3); % fallback
end

f0a = figure; imshow(I_rgb); title('Original RGB'); %[output:372cf65c]
saveas(f0a, fullfile('screenshots', '00_original_rgb.png')); %[output:372cf65c]

% Convert to grayscale (luminance)
if size(I_rgb, 3) == 3
    I = rgb2gray(I_rgb);
else
    I = I_rgb;
end

f0b = figure; imshow(I); title('Grayscale'); %[output:1fe04cd2]
saveas(f0b, fullfile('screenshots', '00_grayscale.png')); %[output:1fe04cd2]

% Basic info (fixed I(:) indexing)
fprintf('Class: %s | Range: [%g, %g] | Size: %d x %d\n', ... %[output:group:1c72548b] %[output:2775a228]
    class(I), double(min(I(:))), double(max(I(:))), size(I,1), size(I,2)); %[output:group:1c72548b] %[output:2775a228]

%%\ 1) Quantization and dynamic range
I8 = I;                                % 8-bit (0..255, 256 levels)
I6 = uint8(floor(double(I)/4)*4);      % ~6 bits (step 4, 64 levels)
I4 = uint8(floor(double(I)/16)*16);    % ~4 bits (step 16, 16 levels)

f1 = figure; montage({I8, I6, I4}, 'Size', [1 3]); %[output:5e00e5ab]
title('Quantization: 8-bit vs ~6-bit vs ~4-bit'); %[output:5e00e5ab]
saveas(f1, fullfile('screenshots', '01_quantization.png')); %[output:5e00e5ab]

%%\ 2) Histogram and contrast stretching
f2a = figure; %[output:8e660ae6]
subplot(1,2,1); imhist(I); title('Histogram (original)'); %[output:8e660ae6]
I_norm    = mat2gray(I);                        % linear scaling to [0,1]
I_stretch = imadjust(I, [0.2 0.8], [0 1]);      % stretch mid-range [51..204] -> [0..255]
subplot(1,2,2); imhist(I_stretch); title('Histogram (stretched)'); %[output:8e660ae6]
saveas(f2a, fullfile('screenshots', '02_histograms.png')); %[output:8e660ae6]

f2b = figure; montage({I, im2uint8(I_norm), im2uint8(I_stretch)}, 'Size', [1 3]); %[output:89181cf7]
title('Original | Normalized | Contrast-stretched'); %[output:89181cf7]
saveas(f2b, fullfile('screenshots', '02_contrast_stretch.png')); %[output:89181cf7]

%%\ 3) Gamma correction (nonlinear amplitude scaling)
I_gamma_low  = imadjust(I, [], [], 0.6); % gamma < 1 brightens mid-tones/shadows
I_gamma_high = imadjust(I, [], [], 1.6); % gamma > 1 darkens mid-tones

f3 = figure; montage({I, I_gamma_low, I_gamma_high}, 'Size', [1 3]); %[output:9a5fb55c]
title('Gamma: original | gamma=0.6 | gamma=1.6'); %[output:9a5fb55c]
saveas(f3, fullfile('screenshots', '03_gamma.png')); %[output:9a5fb55c]

%%\ 4) Sampling and aliasing (downsample then upsample)
scale   = 0.1; % 10% of original spatial dimensions
I_small = imresize(I, scale, 'nearest');          % naive point sampling (no anti-aliasing)
I_back  = imresize(I_small, size(I), 'nearest');  % nearest-neighbor upsampling

f4 = figure; montage({I, I_small, I_back}, 'Size', [1 3]); %[output:565ceeaf]
title('Original | Aggressively downsampled | Upscaled back (aliasing artifacts)'); %[output:565ceeaf]
saveas(f4, fullfile('screenshots', '04_sampling_aliasing.png')); %[output:565ceeaf]

